          { id: "q3-b", label: "TypeScript", correct: true },
          { id: "q3-c", label: "Python", correct: false },
          { id: "q3-d", label: "Ruby", correct: false }
        ]
      }
    ];

    function createChoice(questionId, option) {
      const label = document.createElement("label");
      label.className = "choice";

      const input = document.createElement("input");
      input.type = "checkbox";
      input.name = questionId;
