    const quizData = [
      {
        id: "q1",
        prompt: "Which of these are programming languages?",
        helpText: "Select every option that is a programming language.",
        options: [
          { id: "q1-a", label: "Python", correct: true },
          { id: "q1-b", label: "HTML", correct: false },
          { id: "q1-c", label: "CSS", correct: false },
          { id: "q1-d", label: "SQL", correct: true }
        ]
      },
      {
        id: "q2",
        prompt: "Which languages are commonly used for web development?",
        options: [
          { id: "q2-a", label: "JavaScript", correct: true },
          { id: "q2-b", label: "TypeScript", correct: true },
          { id: "q2-c", label: "COBOL", correct: false },
          { id: "q2-d", label: "Fortran", correct: false }
        ]
      },
      {
        id: "q3",
        prompt: "Which of these are statically typed languages?",
        options: [
          { id: "q3-a", label: "Java", correct: true },
          { id: "q3-b", label: "TypeScript", correct: true },
          { id: "q3-c", label: "Python", correct: false },
          { id: "q3-d", label: "Ruby", correct: false }
        ]
      }
    ];

    function createChoice(questionId, option) {
      const label = document.createElement("label");
      label.className = "choice";

      const input = document.createElement("input");
      input.type = "checkbox";
      input.name = questionId;
      input.value = option.id;
      input.dataset.correct = String(option.correct);

      const text = document.createElement("span");
      text.textContent = option.label;

      label.append(input, text);
      return label;
    }

    function createQuestion(question, index) {
      const field = document.createElement("div");
      field.className = "form-field";

      const group = document.createElement("fieldset");

      const legend = document.createElement("legend");
      legend.textContent = `${index + 1}. ${question.prompt}`;
      group.appendChild(legend);

      if (question.helpText) {
        const help = document.createElement("p");
        help.className = "help-text";
        help.id = `${question.id}-help`;
        help.textContent = question.helpText;
        group.appendChild(help);
        group.setAttribute("aria-describedby", help.id);
      }

      const choices = document.createElement("div");
      choices.className = "choices";
      question.options.forEach((option) => choices.appendChild(createChoice(question.id, option)));

      group.appendChild(choices);
      field.appendChild(group);
      return field;
    }

    function QuizApp() {
      const fragment = document.createDocumentFragment();

      const header = document.createElement("header");
      header.innerHTML = `
        <h1>Computer Languages Quiz</h1>
        <p class="subtitle">A quick multi-select quiz about popular languages and how they are used.</p>
