      form.noValidate = true;

      quizData.forEach((question, index) => {
        form.appendChild(createQuestion(question, index));
      });

      const actions = document.createElement("div");
      actions.className = "actions";

      const result = document.createElement("p");
      result.className = "result";
      result.id = "result";
      result.setAttribute("role", "status");
      result.setAttribute("aria-live", "polite");
      result.textContent = "Choose one or more answers for each question, then submit.";

      const button = document.createElement("button");
      button.type = "submit";
      button.textContent = "Submit Quiz";

      actions.append(result, button);
      form.appendChild(actions);

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        let score = 0;
        const total = quizData.length;

        quizData.forEach((question) => {
          const selected = Array.from(form.querySelectorAll(`input[name="${question.id}"]:checked`));
          const correctIds = question.options.filter((option) => option.correct).map((option) => option.id);
          const selectedIds = selected.map((input) => input.value);
          const isCorrect =
            selectedIds.length === correctIds.length &&
            selectedIds.every((value) => correctIds.includes(value));

          if (isCorrect) {
            score += 1;
          }
        });

        result.innerHTML = `<strong>${score} / ${total}</strong> correct.`;
      });

      fragment.appendChild(form);
      return fragment;
    }

